  s.with_connection(|c|{c.execute("UPDATE pi_tasks SET native_session_id='pi-native',file_verified=1,state='RESULT_READY',result_json=?2 WHERE id=?1",params![task.id,serde_json::json!({"nativeTerminalReceiptId":"terminal-1","lastAssistant":{"text":"PRIVATE_RESULT_BODY"}}).to_string()]).map_err(db_error)?;Ok(())}).unwrap();
